// generated by plugin/scripts/build.mjs from cli/src (piezas 0.7.4); do not edit by hand
// net.js — the ONE place the Piezas CLI sends anything over the network.
//
// Every request goes through netFetch(). It refuses, before anything is sent,
// any destination that is not https on piezas.ai or a subdomain of it, except
// two public, credential-free reads: the npm registry (the SDK version check)
// and Amazon S3 (downloading a file through a short-lived link Piezas itself
// handed out). Those may only be plain GETs with no body and no
// Authorization, Cookie or API-key header.
// So a Piezas sign-in or app key can only ever travel to Piezas. Host
// overrides (PIEZAS_API_BASE, --api-base, PIEZAS_APPS_URL, --apps-url,
// PIEZAS_CONTRACT_URL, a manifest's apiBaseUrl) are checked here too, because
// every request they shape passes through. The list is fixed in this file:
// there is no setting, flag or option that widens it.
//
// Redirects are followed here, not by fetch: every hop is checked like a new
// request. A hop to another origin never carries a sign-in or key (those
// headers are dropped) and never re-sends a body (a 307/308 that would is
// refused; 301/302 from a POST and 303 become a plain GET). So a piezas.ai
// address that redirects elsewhere (a download link to S3) still works for a
// credential-free GET, and nothing else leaves.

const PUBLIC_READ_HOSTS = new Set(['registry.npmjs.org']);
const PUBLIC_READ_SUFFIXES = ['.amazonaws.com'];
const CREDENTIAL_HEADERS = ['authorization', 'cookie', 'x-api-key', 'proxy-authorization'];

export class HostRefusedError extends Error {
  constructor(message) {
    super(message);
    this.name = 'HostRefusedError';
  }
}

function parse(url) {
  try {
    return new URL(String(url));
  } catch {
    return null;
  }
}

// 'piezas' | 'public-read' | null
export function destinationKind(url) {
  const u = parse(url);
  if (!u) return null;
  const host = u.hostname.toLowerCase();
  if (u.protocol === 'https:' && (host === 'piezas.ai' || host.endsWith('.piezas.ai'))) return 'piezas';
  if (u.protocol === 'https:' && (PUBLIC_READ_HOSTS.has(host) || PUBLIC_READ_SUFFIXES.some((s) => host.endsWith(s)))) {
    return 'public-read';
  }
  return null;
}

// Header names, however they were given: a plain object, an array of
// [name, value] pairs, or a Headers instance. Unreadable headers count as
// carrying a credential (refused rather than guessed).
function headerNames(headers) {
  if (!headers) return [];
  try {
    return [...new Headers(headers).keys()];
  } catch {
    return null;
  }
}

function carriesCredential(init = {}) {
  const names = headerNames(init.headers);
  if (names === null) return true;
  return names.some((n) => CREDENTIAL_HEADERS.includes(String(n).toLowerCase()));
}

// The same headers, as a plain object, without sign-in, cookie or key headers.
function withoutCredentials(headers) {
  if (!headers) return headers;
  const out = {};
  for (const [name, value] of new Headers(headers)) {
    if (!CREDENTIAL_HEADERS.includes(name)) out[name] = value;
  }
  return out;
}

// Headers that describe a body, dropped when a redirect turns the request into a GET.
const BODY_HEADERS = ['content-type', 'content-length', 'content-encoding', 'content-language', 'content-location'];
function withoutBodyHeaders(headers) {
  if (!headers) return headers;
  const out = {};
  for (const [name, value] of new Headers(headers)) {
    if (!BODY_HEADERS.includes(name)) out[name] = value;
  }
  return out;
}

function refuse(url, why) {
  const message = `Piezas only connects to piezas.ai addresses. `
    + `${why} Nothing was sent to ${String(url)}. If you set PIEZAS_API_BASE, PIEZAS_APPS_URL, `
    + `PIEZAS_CONTRACT_URL, --api-base or --apps-url, point it at a piezas.ai address.`;
  console.error(`  ${message}`);
  throw new HostRefusedError(message);
}

// checkRequest returns nothing when the request may be sent, and throws
// HostRefusedError (after printing a plain explanation) when it may not.
export function checkRequest(url, init = {}) {
  const kind = destinationKind(url);
  if (kind === 'piezas') return;
  if (kind === 'public-read') {
    const method = String(init.method || 'GET').toUpperCase();
    if (method === 'GET' && init.body === undefined && !carriesCredential(init)) return;
    refuse(url, 'This address may only be read, without any sign-in or key.');
  }
  refuse(url, 'That address is not one of them.');
}

export const MAX_REDIRECTS = 5;
const REDIRECT_STATUSES = new Set([301, 302, 303, 307, 308]);

function refuseRedirect(from, to, why) {
  const message = `Piezas stopped a redirect from ${String(from)} to ${String(to)}: ${why} Nothing was sent there.`;
  console.error(`  ${message}`);
  throw new HostRefusedError(message);
}

// The request to send after a redirect, or a refusal.
function nextHop(status, from, to, init) {
  const sameOrigin = new URL(from).origin === new URL(to).origin;
  const method = String(init.method || 'GET').toUpperCase();
  let next = { ...init };
  // Per the fetch standard: 303 becomes a GET (HEAD stays HEAD); so do 301/302 from a POST.
  if ((status === 303 && method !== 'HEAD') || ((status === 301 || status === 302) && method === 'POST')) {
    next.method = 'GET';
    delete next.body;
    next.headers = withoutBodyHeaders(next.headers);
  } else if (next.body !== undefined && next.body !== null && !sameOrigin) {
    refuseRedirect(from, to, 'it would send this request\'s data to another address.');
  }
  if (!sameOrigin) next.headers = withoutCredentials(next.headers);
  return next;
}

// netFetch(fetchFn, url, init): the gate. fetchFn is the real fetch (or a test
// stub, or the practice-mode simulator); it is only called after the check,
// so whatever fetchFn is, it never sees a refused destination. fetchFn is
// asked not to follow redirects (redirect: 'manual'); each Location is
// checked and followed here, at most MAX_REDIRECTS times.
export async function netFetch(fetchFn, url, init = {}) {
  let current = String(url);
  let request = init;
  checkRequest(current, request);
  for (let hops = 0; ; hops += 1) {
    const response = await fetchFn(current, { ...request, redirect: 'manual' });
    if (!REDIRECT_STATUSES.has(response?.status)) return response;
    const location = response.headers?.get?.('location');
    if (!location) return response;
    let target;
    try {
      target = new URL(location, current).toString();
    } catch {
      return response;
    }
    if (hops >= MAX_REDIRECTS) refuseRedirect(current, target, `more than ${MAX_REDIRECTS} redirects in a row.`);
    try { await response.body?.cancel?.(); } catch { /* nothing to free */ }
    request = nextHop(response.status, current, target, request);
    checkRequest(target, request);
    current = target;
  }
}
